import {neutralFilter,mutateFilter} from './filters.js';
export function initFilterUI({$,getBoard,blocked,preview,commit,status}){
 let draft=null,drag=null,selected=0;const dialog=$('filter-editor'),graph=$('filter-graph'),ns='http://www.w3.org/2000/svg';
 const channel=()=>$('filter-channel').value,points=()=>draft.value.curves[channel()];
 function graphSync(){if(!draft)return;const p=points();selected=Math.min(selected,p.length-1);$('filter-line').setAttribute('points',p.map(([x,y])=>(20+x*260/255)+','+(280-y*260/255)).join(' '));$('filter-points').replaceChildren();p.forEach(([x,y],i)=>{const c=document.createElementNS(ns,'circle');c.setAttribute('cx',20+x*260/255);c.setAttribute('cy',280-y*260/255);c.setAttribute('r',i===selected?7:5);c.dataset.selected=String(i===selected);$('filter-points').append(c);});$('filter-input').value=p[selected][0];$('filter-output').value=p[selected][1];$('filter-input').disabled=selected===0||selected===p.length-1;$('filter-remove').disabled=p.length===2||selected===0||selected===p.length-1;$('filter-point-status').textContent=(selected+1)+' / '+p.length+' points · '+channel();}
 function update(){if(!draft)return;try{if(getBoard()!==draft.base)throw Error('Board changed · cancel and reopen filters');const board=structuredClone(draft.base);mutateFilter(board,draft.id,draft.value);preview(board);$('filter-error').textContent='';$('filter-apply').disabled=false;}catch(e){$('filter-error').textContent=e.message;$('filter-apply').disabled=true;}}
 function cancel(){if(!draft)return;draft=null;drag=null;dialog.close();preview(null);status('Filter cancelled · original artwork restored');}
 const point=e=>{const r=graph.getBoundingClientRect();return [Math.max(0,Math.min(255,((e.clientX-r.left)/r.width*300-20)*255/260)),Math.max(0,Math.min(255,(280-(e.clientY-r.top)/r.height*300)*255/260))];};
 graph.addEventListener('pointerdown',e=>{if(!draft||e.button!==0)return;e.preventDefault();const xy=point(e),p=points(),before=structuredClone(p);let index=p.findIndex(([x,y])=>Math.hypot(x-xy[0],y-xy[1])<12);if(index<0){if(p.length>=8){$('filter-error').textContent='Eight-point limit · remove an interior point first';return;}xy[0]=Math.max(1,Math.min(254,xy[0]));if(p.some(q=>Math.abs(q[0]-xy[0])<1))return;p.push(xy);p.sort((a,b)=>a[0]-b[0]);index=p.indexOf(xy);}selected=index;drag={id:e.pointerId,before,channel:channel()};graph.setPointerCapture(e.pointerId);graphSync();update();});
 graph.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=points(),xy=point(e);if(selected===0||selected===p.length-1)xy[0]=p[selected][0];else xy[0]=Math.max(p[selected-1][0]+1,Math.min(p[selected+1][0]-1,xy[0]));p[selected]=xy;graphSync();update();});
 const finish=(e,cancelled)=>{if(!drag||drag.id!==e.pointerId)return;if(cancelled){draft.value.curves[drag.channel]=drag.before;selected=0;}drag=null;graphSync();update();};graph.addEventListener('pointerup',e=>finish(e,false));graph.addEventListener('pointercancel',e=>finish(e,true));graph.addEventListener('lostpointercapture',e=>{if(drag)finish(e,true);});
 $('filter-channel').onchange=()=>{if(drag){$('filter-channel').value=drag.channel;return;}selected=0;graphSync();};
 for(const id of ['filter-input','filter-output'])$(id).onchange=()=>{if(!draft)return;const p=points(),old=[...p[selected]],value=$(id).value;if(value==='')return;const n=Number(value);if(!Number.isFinite(n)||n<0||n>255||id==='filter-input'&&(selected===0||selected===p.length-1||n<=p[selected-1][0]||n>=p[selected+1][0])){$('filter-error').textContent='Point values must be 0–255; input order must increase';graphSync();return;}p[selected][id==='filter-input'?0:1]=n;graphSync();update();};
 $('filter-remove').onclick=()=>{if(!draft||selected===0||selected===points().length-1)return;points().splice(selected,1);selected=0;graphSync();update();};
 $('filter-reset-channel').onclick=()=>{if(!draft)return;draft.value.curves[channel()]=[[0,0],[255,255]];selected=0;graphSync();update();};
 for(const suffix of ['','-number'])$('filter-blur'+suffix).oninput=()=>{if(!draft)return;const v=$('filter-blur'+suffix).value;$('filter-blur'+(suffix?'':'-number')).value=v;draft.value.blur=v===''?NaN:Number(v);update();};
 $('filter-reset').onclick=()=>{if(!draft)return;draft.value=structuredClone(neutralFilter);selected=0;$('filter-blur').value=$('filter-blur-number').value=0;graphSync();update();};
 $('filter-cancel').onclick=cancel;dialog.addEventListener('cancel',e=>{e.preventDefault();cancel();});window.addEventListener('blur',cancel);
 $('filter-form').addEventListener('submit',e=>{e.preventDefault();if(!draft||drag)return;update();if($('filter-apply').disabled)return;try{commit(draft.id,draft.value,draft.base);draft=null;dialog.close();preview(null);status('Curves & blur saved · Undo restores prior appearance');}catch(err){$('filter-error').textContent=err.message;}});
 return {editing:()=>!!draft,cancel,open(id){if(blocked())return;try{const base=getBoard(),node=base.layers.find(l=>l.id===id)||(base.folders||[]).find(f=>f.id===id);if(!node)throw Error('Filter target missing');const value=structuredClone(node.filter||neutralFilter);mutateFilter(structuredClone(base),id,value);draft={id,base,value};selected=0;$('filter-channel').value='master';$('filter-target').textContent=(base.layers.includes(node)?'Layer: ':'Group: ')+node.name;$('filter-blur').value=$('filter-blur-number').value=value.blur;graphSync();dialog.showModal();update();}catch(e){draft=null;status(e.message,true);}}};
}
